// Locale tags the call converts or reads through the package's code: an
// object with a toString, an element behind a getter, an array-like whose
// length is a getter.
var conversions = 0;
var tag = {
  toString: function () {
    conversions++;
    return conversions === 1 ? "de-DE" : "en-US";
  },
};
var number = (1234.5).toLocaleString([tag]);
var elementReads = 0;
var list = ["sv"];
Object.defineProperty(list, 0, {
  get: function () {
    elementReads++;
    return elementReads === 1 ? "sv" : "en";
  },
});
var order = "ä".localeCompare("z", list);
var lengthReads = 0;
var arrayLike = {
  get length() {
    lengthReads++;
    return 1;
  },
  0: "de-DE",
};
module.exports = {
  number: number,
  conversions: conversions,
  order: order,
  elementReads: elementReads,
  locale: new Intl.NumberFormat(arrayLike).resolvedOptions().locale,
  lengthReads: lengthReads,
};
